mapper.select:
SELECT a.action_id, a.action, a.item_id, a.item_name, a.created_at
  FROM tb_closet_proxy_action a
 WHERE a.pairing_id = #{pairingId}
 ORDER BY a.created_at DESC, a.action_id DESC
 LIMIT #{limit}

UPDATE tb_closet_proxy_action
   SET notified_at = #{now}
 WHERE pairing_id = #{pairingId} AND notified_at IS NULL AND created_at <= #{upTo}
RETURNING action, item_id
